# The helpers documented with `@eval standalone_indiedown_export()`
# are exported from template packages, but stay internal in indiedown.
standalone_indiedown_export <- function() {
  if (identical(utils::packageName(), "indiedown")) "@noRd" else "@export"
}

indiedown_pdf_document_with_asset <- function(includes = NULL, ...) {
  # file preamble
  if (file.exists(file.path(indiedown_path(), "preamble.tex"))) {
    file_preamble <- tempfile(fileext = ".tex")
    txt <- readLines(
      file.path(indiedown_path(), "preamble.tex"),
      encoding = "UTF-8"
    )
    txt <- gsub("<<indiedown_path>>", indiedown_path_tex(), txt, fixed = TRUE)
    writeLines(txt, file_preamble)

    if (is.null(includes)) {
      includes <- rmarkdown::includes(in_header = file_preamble)
    } else {
      if ("in_header" %in% names(includes)) {
        warning(
          "The use of 'includes, in_header' overwrites preamble.tex from asset and may mess up the layout."
        )
      } else {
        includes$in_header <- file_preamble
      }
    }
  }

  ans <- rmarkdown::pdf_document(includes = includes, ...)

  # use pre_processor from asset package or pre_processor_basic, if not present
  file_pre_processor <- file.path(indiedown_path(), "pre_processor.R")
  if (file.exists(file_pre_processor)) {
    env <- environment()
    source(file.path(file_pre_processor), env)
    stopifnot(exists("pre_processor", envir = env))
  } else {
    pre_processor <- pre_processor_basic
  }

  ans$pre_processor <- pre_processor
  repeat_font_message(ans)
}

# The message about a missing font is shown when the pre-processor runs,
# where the log of LaTeX scrolls it away.
# If the render writes the output, the message is shown again
# when rmarkdown::render() exits, after the "Output created" line,
# also when knitting in RStudio, which renders in a separate R session.
repeat_font_message <- function(format) {
  state <- new.env(parent = emptyenv())

  pre_processor <- format$pre_processor
  format$pre_processor <- function(...) {
    state$shown <- NULL
    withCallingHandlers(
      pre_processor(...),
      indiedown_font_message = function(m) state$shown <- m
    )
  }

  # runs only after the output is written
  post_processor <- format$post_processor
  format$post_processor <- function(metadata, input_file, output_file, ...) {
    if (!is.null(post_processor)) {
      output_file <- post_processor(metadata, input_file, output_file, ...)
    }
    state$written <- state$shown
    output_file
  }

  on_exit <- format$on_exit
  format$on_exit <- function() {
    if (is.function(on_exit)) {
      on_exit()
    }
    shown <- state$written
    state$shown <- NULL
    state$written <- NULL
    if (!is.null(shown)) {
      message(shown)
    }
  }

  format
}

pre_processor_basic <- function(
  metadata,
  input_file,
  runtime,
  knit_meta,
  files_dir,
  output_dir
) {
  args <- apply_default_yaml(metadata = metadata)
}

apply_default_yaml <- function(metadata) {
  defaults_txt <- readLines(
    file.path(indiedown_path(), "default.yaml"),
    encoding = "UTF-8"
  )
  defaults <- yaml::yaml.load(defaults_txt)

  # replace <<indiedown_path>> by package path after reading the YAML,
  # so that the characters of the path do not change how it is read,
  # and for fontspec in the value of a `Path=` option, see `fontspec_path()`
  placeholder <- "<<indiedown_path>>"
  for (key in intersect(
    names(defaults),
    c("mainfontoptions", "preferredmainfontoptions")
  )) {
    defaults[[key]] <- as.list(split_font_options(unlist(defaults[[key]])))
  }
  defaults <- rapply(
    as.list(defaults),
    function(x) {
      is_path <- grepl(paste0("^Path=.*", placeholder), x)
      path <- gsub(placeholder, indiedown_path(), x[is_path], fixed = TRUE)
      x[is_path] <- paste0("Path=", fontspec_path(substring(path, 6)))
      gsub(placeholder, indiedown_path_tex(), x, fixed = TRUE)
    },
    classes = "character",
    how = "replace"
  )

  # the main font is resolved separately, also if set in the document
  fonts <- resolve_fonts(metadata, defaults)
  defaults[c(
    "mainfont",
    "mainfontoptions",
    "preferredmainfont",
    "preferredmainfontoptions"
  )] <- NULL

  # do not apply asset defaults if variable set in document
  defaults_applied <- defaults[setdiff(names(defaults), names(metadata))]

  # pandoc variables take precedence over the document's metadata
  args <- list_to_pandoc_args(c(defaults_applied, fonts))

  # pandoc ignores 'header-includes' if includes$in_header is specified
  # https://github.com/jgm/pandoc/issues/3139
  # we can still use `header-includes` by passing it as a command line option to pandoc
  if (!is.null(rmarkdown::metadata$`header-includes`)) {
    args <- c(
      args,
      "--variable",
      paste0(
        "header-includes:",
        paste(rmarkdown::metadata$`header-includes`, collapse = "\n")
      )
    )
  }

  args
}

# The main font is the first of:
#
# 1. the font named in the `mainfont` field of the document,
#    or else in the option `<package>.mainfont`, if it is found;
#    it can be a font file, as a path or as a file name,
#    or the name of a font;
# 2. the preferred font of the format, `preferredmainfont` in default.yaml,
#    with `preferredmainfontoptions`, if it is found:
#    typically a licensed or corporate font that cannot be shipped;
# 3. the fallback font, `mainfont` in default.yaml, with `mainfontoptions`:
#    typically font files shipped in inst/indiedown/fonts and loaded by path.
#
# The preferred font counts as found only if all fonts that it names,
# in `preferredmainfont` and in options such as `BoldFont=`, are found.
# It is looked up as font files first, see `find_font_files()`.
# If the files of all its fonts are found in one folder,
# it is loaded from them by path, like the fallback font,
# because LaTeX may not find an installed font by name,
# such as a font installed for the current user on Windows.
# The bold and italic faces that its options do not name
# are then taken from the files of the same family in that folder,
# see `font_from_folder()`.
# Otherwise, it is loaded by name if the installed fonts include all its fonts.
# A font named in the document or in the option is looked up as font files
# first only where LaTeX does not find fonts by name:
# in the folder of the option `<package>.font_path`, and on Windows,
# in the folder of the fonts installed for the current user, see `font_dirs()`.
# A family name is matched there by the upright face of regular weight,
# and a font file only by its file name, not by its path.
# Otherwise, it is loaded by name if it is installed,
# or as a font file if the file exists or is in the TeX tree.
# A font whose options give a `Path=` or an `Extension=` is a font file
# for fontspec, the name with the extension appended:
# it is left as named, with its options, if the file is in the folder
# of `Path=`, resolved against the working directory,
# or else, without `Path=`, if it is in the TeX tree,
# and LaTeX is left to find its other faces without checking them here.
# The option `<package>.font_path` names a folder with font files,
# for users who cannot install fonts.
# If the installed fonts cannot be listed, see `installed_fonts()`,
# a font named in the document or in the option is left to LaTeX,
# unless its font files were found but their faces could not be told apart,
# or font files that systemfonts could not read were found
# in the folder of the fonts installed for the current user on Windows,
# and the fallback font replaces the preferred one unless its files are found.
# If such font files were found in the folder of the option instead,
# the named font is still left to LaTeX, but with a message,
# because LaTeX does not find a font in that folder by name.
# For a missing font, a message explains how to make it available,
# once per session for each text of the message;
# the output format repeats it at the end of the render.
# If the lookup needed systemfonts but could not load it,
# the message says that this may be why the font lookup failed.
# The `mainfontoptions` of the document are used with a named font
# and appended to those of the preferred or fallback font otherwise.
#
# Returns a list with the pandoc variables `mainfont` and `mainfontoptions`,
# omitting unset ones.
resolve_fonts <- function(
  metadata,
  defaults,
  mainfont = get_indiedown_option("mainfont"),
  font_path = get_indiedown_option("font_path")
) {
  options <- split_font_options(unlist(metadata[["mainfontoptions"]]))

  font <- metadata[["mainfont"]]
  origin <- " from the `mainfont` field of the document"
  if (is.null(font)) {
    font <- mainfont
    origin <- paste0(
      " from the `",
      indiedown_option_name("mainfont"),
      "` option"
    )
  }

  # the installed fonts, listed at most once, and only if needed
  delayedAssign("installed", installed_fonts())
  font_lookup$no_systemfonts <- FALSE
  font_lookup$unidentified <- NULL
  font_lookup$incomplete <- NULL

  # the missing font, see `font_missing()`
  missing <- NULL
  unverified <- FALSE
  if (!is.null(font)) {
    named <- Filter(
      Negate(is.null),
      list(mainfont = font, mainfontoptions = options)
    )
    # a font that fontspec loads from a file, see above,
    # is left as named if the file is found,
    # and is missing otherwise, unless it is found in the folders below
    file <- font
    found <- NULL
    path <- utils::tail(fontspec_option(options, "Path"), 1)
    extension <- utils::tail(fontspec_option(options, "Extension"), 1)
    if (length(c(path, extension)) > 0) {
      file <- paste0(font, extension)
      found <- if (length(path) > 0 && nzchar(path)) {
        file.exists(file.path(path, file))
      } else {
        font_file_installed(file)
      }
      if (!isFALSE(found)) {
        return(named)
      }
    }
    # the folder of the fonts that LaTeX does not find by name
    unseen <- normalize_dirs(font_dirs()$unseen)
    # a font file is looked up in the folders only by its file name
    if (!is_font_file(font) || basename(font) == font) {
      files <- find_font_files(
        font_faces(font, options),
        font_path,
        installed = NULL,
        dirs = list(unseen = unseen)
      )
      from_files <- font_from_folder(named, files, installed)
      if (!is.null(from_files)) {
        return(from_files)
      }
    }
    if (is.null(defaults[["mainfont"]])) {
      return(named)
    }
    if (is.null(found)) {
      found <- fonts_installed(font, installed)
    }
    missing <- font_missing(
      paste0("Font \"", font, "\"", origin),
      file,
      font_install_hint(file)
    )
    # without a list of the installed fonts, a font is left to LaTeX,
    # unless its font files could not be loaded,
    # or it may be among the font files that LaTeX does not find by name
    # and that could not be identified
    unread <- c(
      font_lookup$incomplete,
      intersect(font_lookup$unidentified, unseen)
    )
    if (isTRUE(found) || (is.na(found) && length(unread) == 0)) {
      # it may also be among the font files that could not be identified
      # in the other folders, which LaTeX does not see either
      if (is.na(found) && length(font_lookup$unidentified) > 0) {
        show_font_message(paste0(
          missing$text,
          " is left to LaTeX, which may not find it.\n",
          missing$systemfonts,
          "If LaTeX does not find it, ",
          missing$hint,
          ".\n"
        ))
      }
      return(named)
    }
    # the options were meant for the missing font
    options <- NULL
    unverified <- is.na(found)
  }

  fonts <- list(
    mainfont = defaults[["mainfont"]],
    mainfontoptions = unlist(defaults[["mainfontoptions"]])
  )
  preferred <- list(
    mainfont = defaults[["preferredmainfont"]],
    mainfontoptions = unlist(defaults[["preferredmainfontoptions"]])
  )
  # the font that is used, by name
  used <- fonts$mainfont
  if (!is.null(preferred$mainfont)) {
    faces <- font_faces(preferred$mainfont, preferred$mainfontoptions)
    files <- find_font_files(faces, font_path, installed)
    from_files <- font_from_folder(preferred, files, installed)
    if (!is.null(from_files)) {
      fonts <- from_files
      used <- preferred$mainfont
    } else if (isTRUE(all(fonts_installed(faces, installed)))) {
      fonts <- preferred
      used <- preferred$mainfont
    } else if (is.null(missing)) {
      missing <- font_missing(
        paste0("Preferred font \"", preferred$mainfont, "\""),
        preferred$mainfont,
        preferred_font_hint(preferred$mainfont, font_path)
      )
    }
  }

  if (!is.null(missing)) {
    show_font_message(paste0(
      missing$text,
      if (unverified) {
        " could not be verified, using \""
      } else {
        " was not found, using \""
      },
      used,
      "\" instead.\n",
      missing$systemfonts,
      "To use it, ",
      missing$hint,
      ".\n"
    ))
  }

  fonts$mainfontoptions <- c(fonts$mainfontoptions, options)
  Filter(Negate(is.null), fonts)
}

# Shows the message about a missing font, once per session for each `text`
show_font_message <- function(text) {
  if (is.null(font_messages[[text]])) {
    font_messages[[text]] <- TRUE
    message(structure(
      class = c("indiedown_font_message", "message", "condition"),
      list(message = text, call = NULL)
    ))
  }
}

# The value of the option `<package>.<name>`,
# where `<package>` is the package that holds this file, such as `mydown`,
# or `default` if the option is not set.
# This is how a template package reads its options,
# e.g. `font_path = get_indiedown_option("font_path")` in a function signature.
get_indiedown_option <- function(name, default = NULL) {
  getOption(indiedown_option_name(name), default)
}

# The name of the option `<package>.<name>`, as users set it.
# The package is the one that holds this file, found from `env`.
# Where this file is not part of a package, such as when it is sourced,
# or `env` is the global environment, the package is taken to be `indiedown`.
indiedown_option_name <- function(
  name,
  env = environment(indiedown_option_name)
) {
  package <- utils::packageName(env)
  paste0(if (is.null(package)) "indiedown" else package, ".", name)
}

# The texts of the messages and warnings about fonts shown in this session
font_messages <- new.env(parent = emptyenv())

# The state of the current lookup:
# `no_systemfonts` is TRUE if it needed systemfonts but could not load it,
# see `has_systemfonts()`,
# `unidentified` holds the folders whose font files it could not identify
# without systemfonts, see `find_font_files()`,
# and `incomplete` the folder whose files of a font it could not load,
# because it could not tell the faces apart, see `font_from_folder()`
font_lookup <- new.env(parent = emptyenv())

# What systemfonts read from font files in this session, by path,
# each with the modification time of the file, see `font_file_info()`
font_info_cache <- new.env(parent = emptyenv())

# A missing `font`: the start of the message about it, in `text`,
# and how to make it available, in `hint`.
# If the lookup needed systemfonts but could not load it,
# `systemfonts` says so, and the hint begins with installing it.
# If it found font files whose faces it could not tell apart,
# `systemfonts` names their folder,
# and the hint explains how to name all faces of the font instead.
# If there were font files that it could not identify,
# `systemfonts` names their folders,
# and the hint also explains how to name the files so that they are found.
font_missing <- function(text, font, hint) {
  if (!isTRUE(font_lookup$no_systemfonts)) {
    return(list(text = text, systemfonts = NULL, hint = hint))
  }
  systemfonts <- paste(
    "The systemfonts package could not be loaded,",
    "which may be why the font lookup failed"
  )
  install <- paste(
    "install systemfonts 1.3.0 or later",
    "with `install.packages(\"systemfonts\")`,\nor"
  )
  incomplete <- font_lookup$incomplete
  if (!is.null(incomplete)) {
    return(list(
      text = text,
      systemfonts = paste0(
        systemfonts,
        ":\nwithout it, the bold and italic faces of the font files in \"",
        incomplete,
        "\" cannot be identified.\n"
      ),
      hint = paste(
        install,
        "name all faces of the font in its options,",
        "with `BoldFont=`, `ItalicFont=` and `BoldItalicFont=`"
      )
    ))
  }
  unidentified <- font_lookup$unidentified
  if (is.null(unidentified)) {
    return(list(
      text = text,
      systemfonts = paste0(systemfonts, ".\n"),
      hint = paste(install, hint)
    ))
  }
  list(
    text = text,
    systemfonts = paste0(
      systemfonts,
      ":\nwithout it, the font files in \"",
      paste(unidentified, collapse = "\", \""),
      "\" cannot be identified.\n"
    ),
    hint = paste0(
      install,
      " ",
      hint,
      ".\nIf its font files are among those that cannot be identified, ",
      "copy them to a folder,\n",
      "rename them to the font names that are looked up, such as \"",
      if (is_font_file(font)) font else paste0(font, ".otf"),
      "\",\nand set `options(",
      indiedown_option_name("font_path"),
      " = \"<folder>\")`"
    )
  )
}

# How to make the missing preferred font available
preferred_font_hint <- function(font, font_path) {
  path_option <- indiedown_option_name("font_path")
  if (!is.null(font_path)) {
    return(paste0(
      "check that the folder \"",
      paste(font_path, collapse = "\", \""),
      "\" from the option `",
      path_option,
      "` holds its font files"
    ))
  }
  paste0(
    font_install_hint(font),
    ",\nor set `options(",
    path_option,
    " = \"<folder>\")` to a folder with its font files"
  )
}

# The font and the fonts that its fontspec options name for other faces,
# such as `BoldFont=`, where `*` stands for the font, as in fontspec
font_faces <- function(font, options) {
  pattern <- "^[[:alpha:]]+Font="
  faces <- sub(pattern, "", grep(pattern, options, value = TRUE))
  unique(c(font, gsub("*", font, faces, fixed = TRUE)))
}

# The pandoc variables that load `font`, a list with `mainfont`
# and `mainfontoptions`, from its font `files`, named by face as in
# `font_faces()`: with `Path=` and file names, like the fallback font
font_from_files <- function(font, files) {
  pattern <- "^([[:alpha:]]+Font=)(.*)$"
  # the files are in one folder, which replaces a `Path=` of the options,
  # and are named with their extensions, which replace an `Extension=`
  options <- grep(
    "^\\s*(Path|Extension)\\s*=",
    as.character(font$mainfontoptions),
    value = TRUE,
    invert = TRUE
  )
  is_face <- grepl(pattern, options)
  faces <- sub(pattern, "\\2", options[is_face])
  faces <- gsub("*", font$mainfont, faces, fixed = TRUE)
  keys <- sub(pattern, "\\1", options[is_face])
  options[is_face] <- paste0(keys, basename(files[faces]))
  list(
    mainfont = basename(files[[font$mainfont]]),
    mainfontoptions = c(
      paste0("Path=", fontspec_path(paste0(dirname(files[[1]]), "/"))),
      options
    )
  )
}

# The values of the fontspec option `key` in `options`,
# without the spaces and one level of braces around them
# The fontspec options in `x`, a character vector whose elements may each hold
# several options joined by commas, as one string in a YAML file or a document.
# The commas inside braces belong to the value of an option and do not split it.
split_font_options <- function(x) {
  if (is.null(x)) {
    return(NULL)
  }
  split_one <- function(string) {
    parts <- character()
    start <- 1L
    depth <- 0L
    chars <- strsplit(string, "")[[1]]
    for (i in seq_along(chars)) {
      if (chars[[i]] == "{") {
        depth <- depth + 1L
      } else if (chars[[i]] == "}") {
        depth <- max(depth - 1L, 0L)
      } else if (chars[[i]] == "," && depth == 0L) {
        parts <- c(parts, substr(string, start, i - 1L))
        start <- i + 1L
      }
    }
    if (length(parts) == 0) {
      return(string)
    }
    trimws(c(parts, substr(string, start, nchar(string))))
  }
  x <- unlist(lapply(as.character(x), split_one))
  x <- x[nzchar(x)]
  if (length(x) > 0) x else NULL
}

fontspec_option <- function(options, key) {
  pattern <- paste0("^\\s*", key, "\\s*=\\s*(.*?)\\s*$")
  values <- grep(pattern, as.character(options), value = TRUE, perl = TRUE)
  values <- sub(pattern, "\\1", values, perl = TRUE)
  sub("^[{](.*)[}]$", "\\1", values)
}

# The folder `path` as the value of a fontspec option such as `Path=`.
# The characters that LaTeX reads as commands or comments
# are written as the strings of expl3 that hold them,
# with the spaces if there are such characters or a run of spaces,
# because a space after a command is dropped, and LaTeX reads a run of spaces as one.
# A double quote cannot be written: fontspec quotes the file name for XeTeX,
# which has no way to escape it, so a folder with a double quote is not supported.
# A value with a comma or an equals sign is put in braces,
# which keep the fontspec options apart.
# On Windows, backslashes separate folders, and become forward slashes.
fontspec_path <- function(path, windows = .Platform$OS.type == "windows") {
  if (windows) {
    path <- gsub("\\", "/", path, fixed = TRUE)
  }
  strings <- c(
    `\\` = "c_backslash_str",
    `%` = "c_percent_str",
    `#` = "c_hash_str",
    `~` = "c_tilde_str",
    `{` = "c_left_brace_str",
    `}` = "c_right_brace_str",
    `^` = "c_circumflex_str",
    ` ` = "c_space_tl"
  )
  vapply(
    path,
    function(path) {
      chars <- strsplit(path, "")[[1]]
      escape <- chars %in% names(strings)
      if (any(escape & chars != " ") || grepl("  ", path, fixed = TRUE)) {
        chars[escape] <- paste0(
          "\\csname ",
          strings[chars[escape]],
          "\\endcsname "
        )
      }
      value <- paste(chars, collapse = "")
      if (any(chars %in% c(",", "="))) paste0("{", value, "}") else value
    },
    "",
    USE.NAMES = FALSE
  )
}

# The pandoc variables that load `font` from its font `files`,
# see `font_from_files()`, or NULL if `files` is NULL.
# fontspec finds the bold, italic and bold italic faces of a font
# that is loaded by name, but not of a font that is loaded from a file.
# The faces that the options of `font` do not name
# are therefore taken from the files of the same family in the folder,
# see `font_styles()` and `other_faces()`.
# If the faces of these files cannot be told apart,
# the font is loaded from its files only if its options name all faces;
# otherwise this returns NULL and notes the folder in `font_lookup$incomplete`.
font_from_folder <- function(font, files, installed = installed_fonts()) {
  if (is.null(files)) {
    return(NULL)
  }
  fonts <- font_from_files(font, files)
  pattern <- "^([[:alpha:]]+Font)=(.*)$"
  options <- grep(pattern, as.character(font$mainfontoptions), value = TRUE)
  keys <- sub(pattern, "\\1", options)
  unnamed <- setdiff(c("BoldFont", "ItalicFont", "BoldItalicFont"), keys)
  if (length(unnamed) == 0) {
    return(fonts)
  }

  main <- files[[font$mainfont]]
  bold <- sub(pattern, "\\2", options[keys == "BoldFont"])
  bold <- gsub("*", font$mainfont, bold, fixed = TRUE)
  bold <- utils::head(unname(files[bold]), 1)
  styles <- font_styles(main, installed)
  other <- if (!is.null(styles)) other_faces(styles, main, bold, unnamed)
  if (is.null(other)) {
    font_lookup$incomplete <- dirname(main)
    return(NULL)
  }
  fonts$mainfontoptions <- c(
    fonts$mainfontoptions,
    sprintf("%s=%s", names(other), basename(other))
  )
  fonts
}

# The `path`, `family`, `weight` and `italic` of the font files
# in the folder of the font file `main`,
# with the weight on the scale of fontconfig, see `font_weight()`:
# from the `installed` fonts if they list `main`, see `installed_fonts()`,
# or else read with systemfonts, see `font_file_info()`.
# NULL if systemfonts is needed but cannot be loaded.
font_styles <- function(main, installed) {
  dir <- dirname(main)
  styles <- installed$styles
  if (path_key(main) %in% path_key(styles$path)) {
    in_dir <- path_key(dirname(styles$path)) == path_key(dir)
    return(lapply(styles, `[`, in_dir))
  }
  if (!has_systemfonts()) {
    return(NULL)
  }
  files <- list.files(
    dir,
    "[.](otf|ttf)$",
    full.names = TRUE,
    ignore.case = TRUE
  )
  info <- lapply(files, font_file_info)
  list(
    path = files,
    family = vapply(info, `[[`, "", "family"),
    weight = vapply(info, `[[`, numeric(1), "weight"),
    italic = vapply(info, `[[`, logical(1), "italic")
  )
}

# The font files of the `unnamed` faces, of "BoldFont", "ItalicFont"
# and "BoldItalicFont", among the font files of `styles`, see `font_styles()`,
# named by face, chosen as fontconfig chooses the faces of an installed font:
# of the family of the font file `main`,
# upright with the weight closest to bold for the bold face,
# italic with the weight closest to that of `main` for the italic face,
# and italic with the weight closest to that of the `bold` face,
# the named one or else the chosen one, for the bold italic face.
# The bold face is heavier than `main`.
# A face that the family lacks is left out, as fontspec leaves it out.
# NULL if the family, weight or slant of `main` is not known.
other_faces <- function(styles, main, bold, unnamed) {
  i <- match(path_key(main), path_key(styles$path))
  weight <- styles$weight[i]
  family <- styles$family[i]
  if (is.na(weight) || is.na(styles$italic[i]) || is.na(family)) {
    return(NULL)
  }
  same <- tolower(styles$family) %in% tolower(family)
  in_family <- same & !is.na(styles$weight) & !is.na(styles$italic)
  closest <- function(italic, to, heavier = FALSE) {
    ok <- in_family &
      styles$italic == italic &
      (!heavier | styles$weight > weight)
    if (!any(ok)) {
      return(NULL)
    }
    styles$path[ok][[which.min(abs(styles$weight[ok] - to))]]
  }

  if ("BoldFont" %in% unnamed) {
    bold <- closest(italic = FALSE, to = 200, heavier = TRUE)
  }
  bold_weight <- styles$weight[match(path_key(bold), path_key(styles$path))]
  if (length(bold_weight) == 0 || is.na(bold_weight)) {
    bold_weight <- 200
  }
  faces <- list(
    BoldFont = bold,
    ItalicFont = closest(italic = TRUE, to = weight),
    BoldItalicFont = if (length(bold) > 0) {
      closest(italic = TRUE, to = bold_weight)
    }
  )
  c(character(), unlist(faces[unnamed]))
}

# The font files of `faces`, one for each, all in the same folder,
# named by face, or NULL if they are not found.
# The folder `font_path` and the folders of `dirs`, see `font_dirs()`,
# are searched by file name, with or without the extension, each folder once.
# Faces named as font files, with the extension, are only found so.
# Otherwise, the files in the folder `font_path` are identified next
# by the names that systemfonts reads from them, see `font_file_names()`,
# then the `installed` fonts by the names that they list,
# see `installed_fonts()`,
# and last the files in the other folders that the list does not cover,
# by the names that systemfonts reads from them:
# those in the `unseen` folder,
# and in the `user` folders if the installed fonts cannot be listed.
# Folders whose files could not be read without systemfonts
# are noted in `font_lookup$unidentified`.
find_font_files <- function(
  faces,
  font_path = get_indiedown_option("font_path"),
  installed = installed_fonts(),
  dirs = font_dirs()
) {
  files <- list()
  folders <- c(font_path, dirs$unseen, dirs$user, dirs$system)
  for (dir in normalize_dirs(folders)) {
    files[[dir]] <- list_font_files(dir)
    # with or without the extension
    names <- basename(files[[dir]])
    found <- match_font_files(
      faces,
      rep(files[[dir]], 2),
      c(sub("[.][^.]*$", "", names), names)
    )
    if (!is.null(found)) {
      return(found)
    }
  }
  # font files named with their extension are found by file name only
  if (all(is_font_file(faces))) {
    return(NULL)
  }

  identify <- function(dirs) {
    for (dir in dirs) {
      if (length(files[[dir]]) == 0) {
        next
      }
      names <- font_file_names(files[[dir]])
      if (is.null(names)) {
        font_lookup$unidentified <- c(font_lookup$unidentified, dir)
        next
      }
      found <- match_font_files(faces, names$path, names$name)
      if (!is.null(found)) {
        return(found)
      }
    }
    NULL
  }

  found <- identify(normalize_dirs(font_path))
  if (!is.null(found)) {
    return(found)
  }
  found <- match_font_files(faces, installed$path, installed$name)
  if (!is.null(found)) {
    return(found)
  }
  unlisted <- normalize_dirs(c(dirs$unseen, if (is.null(installed)) dirs$user))
  identify(setdiff(unlisted, normalize_dirs(font_path)))
}

# The folders `dirs` as absolute paths with forward slashes, each once
normalize_dirs <- function(dirs) {
  unique(normalizePath(as.character(dirs), "/", mustWork = FALSE))
}

# The `.otf` and `.ttf` files in `dir` and its subfolders,
# down to `depth` levels and at most `limit` files,
# so that large font collections are searched in bounded time.
list_font_files <- function(dir, depth = 3, limit = 5000) {
  files <- list.files(
    dir,
    "[.](otf|ttf)$",
    full.names = TRUE,
    ignore.case = TRUE
  )
  if (depth > 0) {
    for (subdir in list.dirs(dir, recursive = FALSE)) {
      if (length(files) >= limit) {
        break
      }
      files <- c(files, list_font_files(subdir, depth - 1, limit))
    }
  }
  utils::head(files, limit)
}

# The folders of the fonts installed for the current user and for all users,
# where fc-list may not see them, in `user` and `system`.
# TeX Live's fontconfig on Windows, which XeTeX and fc-list use,
# only sees the fonts installed for all users,
# so LaTeX does not find the fonts in the `unseen` folder by name.
# On Linux, the folders are those that fontconfig reads,
# so that fonts are found also where `fc-list` is not installed,
# as in minimal containers.
# If the option `<package>.system_fonts` is `FALSE`, there are none,
# and systemfonts does not list the installed fonts either,
# see `installed_fonts()`:
# the lookup then sees only the folder of the option `<package>.font_path`
# and the fonts that fc-list lists,
# which a `FONTCONFIG_FILE` can restrict, as in snapshot tests.
font_dirs <- function(
  sysname = Sys.info()[["sysname"]],
  system_fonts = get_indiedown_option("system_fonts", TRUE)
) {
  if (isFALSE(system_fonts)) {
    return(list())
  }
  switch(
    sysname,
    Windows = {
      user <- file.path(Sys.getenv("LOCALAPPDATA"), "Microsoft/Windows/Fonts")
      list(
        user = user,
        system = file.path(Sys.getenv("WINDIR"), "Fonts"),
        unseen = user
      )
    },
    Darwin = list(user = "~/Library/Fonts", system = "/Library/Fonts"),
    list(
      user = c(
        "~/.local/share/fonts",
        "~/.fonts",
        if (nzchar(Sys.getenv("XDG_DATA_HOME"))) {
          file.path(Sys.getenv("XDG_DATA_HOME"), "fonts")
        }
      ),
      system = c("/usr/local/share/fonts", "/usr/share/fonts")
    )
  )
}

# The first files, by folder, whose `font_names` match `faces`:
# one file for each face, all in the same folder, named by face, or NULL.
# Faces that are aliases, such as a family name and a PostScript name,
# can share a file.
# Font collections are skipped, because fontspec would need the index,
# and so are paths that are NA, see `installed_fonts()`.
match_font_files <- function(faces, paths, font_names) {
  if (is.null(font_names)) {
    return(NULL)
  }
  keep <- !is.na(paths) & grepl("[.](otf|ttf)$", paths, ignore.case = TRUE)
  paths <- paths[keep]
  font_names <- tolower(font_names[keep])
  for (dir in unique(dirname(paths))) {
    in_dir <- dirname(paths) == dir
    files <- paths[in_dir][match(tolower(faces), font_names[in_dir])]
    if (!anyNA(files)) {
      names(files) <- faces
      return(files)
    }
  }
  NULL
}

# The names of the fonts in `files`, as a list with the `path` of each file
# and its `name`, both repeated as needed:
# the PostScript name of each file,
# and the family name of the upright face of regular weight of each family.
# NULL if systemfonts cannot be loaded.
font_file_names <- function(files) {
  if (!has_systemfonts()) {
    return(NULL)
  }
  info <- lapply(files, font_file_info)
  name <- vapply(info, `[[`, "", "name")
  family <- vapply(info, `[[`, "", "family")
  italic <- vapply(info, `[[`, logical(1), "italic")
  weight <- vapply(info, `[[`, numeric(1), "weight")
  # upright first, then by the distance of the weight from regular
  by_rank <- order(italic, abs(weight - 80))
  regular <- by_rank[!duplicated(family[by_rank]) & !is.na(family[by_rank])]
  list(path = c(files, files[regular]), name = c(name, family[regular]))
}

# The PostScript `name`, the `family`, whether `italic`,
# and the `weight` of a font file, see `font_weight()`,
# with NA where they cannot be read, and with `italic` FALSE then.
# They are read once per session for each file,
# and again if the file is modified.
font_file_info <- function(file) {
  mtime <- file.mtime(file)
  cached <- font_info_cache[[file]]
  if (identical(cached$mtime, mtime)) {
    return(cached)
  }
  cached <- tryCatch(
    {
      info <- systemfonts::font_info(path = file)
      list(
        name = as.character(info$name[[1]]),
        family = as.character(info$family[[1]]),
        italic = isTRUE(info$italic[[1]]),
        weight = font_weight(info$weight[[1]])
      )
    },
    error = function(e) {
      list(
        name = NA_character_,
        family = NA_character_,
        italic = FALSE,
        weight = NA_real_
      )
    }
  )
  cached$mtime <- mtime
  font_info_cache[[file]] <- cached
  cached
}

# The weight of fonts on the scale of fontconfig, where 80 is regular
# and 200 is bold, from the `level` that systemfonts reports
font_weight <- function(level) {
  levels <- c(
    "thin",
    "ultralight",
    "light",
    "normal",
    "medium",
    "semibold",
    "bold",
    "ultrabold",
    "heavy"
  )
  c(0, 40, 50, 80, 100, 180, 200, 205, 210)[match(as.character(level), levels)]
}

# TRUE if systemfonts can be loaded in version 1.3.0 or later,
# the first that reads the PostScript names of font files.
# Otherwise FALSE, with a warning once per session
# if an earlier version is installed,
# and the current lookup notes that it could not load systemfonts.
# It is called only when the lookup needs systemfonts.
has_systemfonts <- function() {
  if (rlang::is_installed("systemfonts", version = "1.3.0")) {
    return(TRUE)
  }
  font_lookup$no_systemfonts <- TRUE
  if (rlang::is_installed("systemfonts")) {
    text <- paste0(
      "The font lookup needs systemfonts 1.3.0 or later, but version ",
      utils::packageVersion("systemfonts"),
      " is installed.\n",
      "Update it with `install.packages(\"systemfonts\")`."
    )
    if (is.null(font_messages[[text]])) {
      font_messages[[text]] <- TRUE
      warning(text, call. = FALSE)
    }
  }
  FALSE
}

# TRUE for each font that is found, FALSE for a missing one,
# and NA if this cannot be determined:
# for a font name if the `installed` fonts cannot be listed,
# and for a font file name if kpsewhich is not available.
fonts_installed <- function(fonts, installed = installed_fonts()) {
  is_file <- is_font_file(fonts)
  found <- rep(NA, length(fonts))
  found[is_file] <- vapply(fonts[is_file], font_file_installed, logical(1))
  if (!all(is_file)) {
    names <- installed_font_names(installed)
    if (!is.null(names)) {
      found[!is_file] <- tolower(fonts[!is_file]) %in% tolower(names)
    }
  }
  found
}

font_file_installed <- function(font) {
  if (file.exists(font)) {
    return(TRUE)
  }
  if (basename(font) != font) {
    return(FALSE)
  }
  # a file name: look it up in the TeX tree
  kpsewhich <- Sys.which("kpsewhich")
  if (!nzchar(kpsewhich)) {
    return(NA)
  }
  found <- suppressWarnings(
    system2(kpsewhich, shQuote(font), stdout = TRUE, stderr = FALSE)
  )
  length(found) > 0
}

is_font_file <- function(font) {
  grepl("[.](otf|ttf|otc|ttc)$", font, ignore.case = TRUE)
}

# The installed system fonts, as a list with the `path` of each font file
# and its `name`s, both repeated as needed,
# the `family` names of all fonts,
# and the `styles` of their font files, as `font_styles()` returns them,
# or NULL if they cannot be listed.
# The names are the PostScript and full names with fc-list,
# and the PostScript names with systemfonts.
# The `path` is NA for the named instances of a variable font
# and for the fonts of a font collection after the first,
# because loading the file by path loads its first font.
# fc-list lists the fonts that fontconfig finds,
# where XeTeX and LuaTeX look for system fonts on Linux
# and with TeX Live on Windows.
# It runs as a new process, so it sees the current FONTCONFIG_FILE,
# which tests can set to hide the system fonts.
# systemfonts covers systems without fc-list, such as macOS,
# if it can be loaded, see `has_systemfonts()`;
# it caches the font list for the session,
# so a font installed since needs a restart of R to be seen.
# The cache is not reset with `systemfonts::reset_font_cache()`,
# which also changes the fonts that graphics devices find.
# The fonts that it lists in the `unseen` folder, see `font_dirs()`,
# are left out, because LaTeX does not find them by name.
# It does not see FONTCONFIG_FILE,
# so it is not used if the option `<package>.system_fonts` is `FALSE`,
# see `font_dirs()`, and no font is listed then.
installed_fonts <- function(
  system_fonts = get_indiedown_option("system_fonts", TRUE)
) {
  fc_list <- Sys.which("fc-list")
  if (nzchar(fc_list)) {
    format <- paste0(
      "%{file}\\t%{index}\\t%{postscriptname}\\t%{fullname}\\t",
      "%{family}\\t%{weight}\\t%{slant}\\n"
    )
    out <- suppressWarnings(system2(
      fc_list,
      c("--format", shQuote(format)),
      stdout = TRUE,
      stderr = FALSE
    ))
    fields <- lapply(strsplit(out, "\t", fixed = TRUE), function(x) {
      c(x, character(7))[1:7]
    })
    field <- function(i) vapply(fields, `[[`, "", i)
    split_names <- function(x) trimws(unlist(strsplit(x, ",", fixed = TRUE)))
    number <- function(x) suppressWarnings(as.numeric(x))
    return(installed_font_list(
      path = field(1),
      index = number(field(2)),
      names = lapply(fields, function(x) split_names(x[3:4])),
      families = lapply(field(5), split_names),
      weight = number(field(6)),
      italic = number(field(7)) > 0
    ))
  }

  if (isFALSE(system_fonts)) {
    return(installed_font_list())
  }
  if (!has_systemfonts()) {
    return(NULL)
  }
  fonts <- systemfonts::system_fonts()
  fonts <- fonts[!in_dirs(fonts$path, font_dirs()$unseen), ]
  installed_font_list(
    path = fonts$path,
    index = fonts$index,
    names = as.list(fonts$name),
    families = as.list(fonts$family),
    weight = font_weight(fonts$weight),
    italic = fonts$italic
  )
}

# The list that `installed_fonts()` returns,
# from the `path`, `index`, `names`, `families`, `weight` and `italic`
# of each font, where `weight` is on the scale of fontconfig.
# A font at an `index` other than 0 is not loaded by loading its file,
# so its path is NA, and it has no styles.
installed_font_list <- function(
  path = character(),
  index = numeric(),
  names = list(),
  families = list(),
  weight = numeric(),
  italic = logical()
) {
  first <- index %in% 0
  family <- vapply(
    families,
    function(x) if (length(x) > 0) x[[1]] else NA_character_,
    ""
  )
  path <- as.character(path)
  path[!first] <- NA
  list(
    path = rep(path, lengths(names)),
    name = as.character(unlist(names)),
    family = as.character(unlist(families)),
    styles = list(
      path = path[first],
      family = family[first],
      weight = as.numeric(weight[first]),
      italic = as.logical(italic[first])
    )
  )
}

# TRUE for the `paths` in one of the folders `dirs` or in their subfolders
in_dirs <- function(paths, dirs) {
  paths <- path_key(paths)
  found <- rep(FALSE, length(paths))
  for (dir in sub("/*$", "/", path_key(dirs))) {
    found <- found | startsWith(paths, dir)
  }
  found
}

# `paths` for comparing them: with forward slashes,
# and in lower case on Windows, where paths ignore case
path_key <- function(paths, windows = .Platform$OS.type == "windows") {
  paths <- gsub("\\", "/", as.character(paths), fixed = TRUE)
  if (windows) tolower(paths) else paths
}

# Family, full and PostScript names of the `installed` fonts,
# or NULL if they cannot be listed
installed_font_names <- function(installed = installed_fonts()) {
  c(installed$family, installed$name)
}

font_install_hint <- function(font, sysname = Sys.info()[["sysname"]]) {
  if (is_font_file(font)) {
    return(
      "check the path, relative paths start at the directory of the document"
    )
  }
  switch(
    sysname,
    Windows = paste(
      "install its font files for the current user",
      "(Settings > Personalization > Fonts, or right-click > Install),",
      "and restart R"
    ),
    Darwin = paste(
      "open its font files and click \"Install\" in Font Book,",
      "and restart R"
    ),
    "copy its font files to ~/.local/share/fonts, and restart R"
  )
}

# list <- list(
#   indent = TRUE,
#   `compact-title` = TRUE,
#   classoption = c("twocolumn", "landscape")
# )
# list_to_pandoc_args(list)
list_to_pandoc_args <- function(list) {
  is_logical <- vapply(list, is.logical, TRUE)
  is_character <- vapply(list, is.character, TRUE)

  # prepare logicals (TRUE FALSE to yes no)
  list[is_logical] <- lapply(list[is_logical], function(x) {
    ifelse(x, "yes", "no")
  })
  # prepare character (comma separate multiple values)
  list[is_character] <- lapply(list[is_character], paste, collapse = ",")

  vars <- paste0(names(list), ":", unlist(list))

  zip <- function(x, y) {
    x <- rep_len(x, length(y))
    m <- matrix(c(x, y), nrow = 2, byrow = TRUE)
    as.vector(m)
  }
  zip("--variable", vars)
}

#' Path helpers
#'
#' `indiedown_path()` creates a path to this package's indiedown assets,
#' located at `inst/indiedown`.
#'
#' @param ... Path components, passed on to `system.file()`.
#' @return Character string, path to this package's indiedown assets
#' @examples
#' indiedown_path()
#' @eval standalone_indiedown_export()
indiedown_path <- function(...) {
  system.file("indiedown", ..., package = utils::packageName())
}

#' Path to indiedown assets, usable in LaTeX
#'
#' `indiedown_path_tex()` creates a path that is usable in LaTeX,
#' with all special characters escaped.
#'
#' @rdname indiedown_path
#' @eval standalone_indiedown_export()
indiedown_path_tex <- function(...) {
  sanitize_tex(indiedown_path(...))
}


sanitize_tex <- function(path) {
  # on win, tex does not like \\
  path <- gsub("\\", "/", fixed = TRUE, path)
  path <- gsub("~", "\\string~", path, fixed = TRUE)
  path
}

#' Glue LaTeX Code for Use in R Markdown
#'
#' Use the function to wrap literal LaTeX code in R. Use a raw string input
#' (`r"()"`) to automatically escape quotes and backslashes, as they are common
#' in LaTeX. Expressions enclosed by `<<` and `>>` will be evaluated as R code.
#'
#' `indiedown_glue()` uses a different default than the underlying
#' `glue::glue()` (`<<` and `>>`), because braces are so common in LaTeX.
#' Doubling the full delimiter (`<<<<` and `>>>>`) escapes it.
#'
#' @param x Character, often as a raw string (`r"()"`)
#' @param .open,.close The opening and closing delimiter.
#' @return Object of class `"knit_asis"` (so that knitr will treat it as is). Usually LaTeX code.
#' @eval standalone_indiedown_export()
#' @examples
#' x <- "something"
#' indiedown_glue(r"(\LaTeX\ code with <<x>> substituted )")
#'
indiedown_glue <- function(x, .open = "<<", .close = ">>") {
  ans <- glue::glue(x, .envir = sys.frame(-1), .open = .open, .close = .close)
  knitr::asis_output(ans)
}


# compatible with older versions. We can use raw strings from 4.0 on.
read_tex <- function(file) {
  paste(
    readLines(indiedown_path("tex", file), encoding = "UTF-8"),
    collapse = "\n"
  )
}

#' Set Default Value
#'
#' Set default value of an argument. If `x` is `NULL`, `default` is used.
#'
#' @param x Character string, or `NULL`
#' @param default If `x` is `NULL`, `default` is used.
#'
#' @return Character string
#' @examples
#' default(NULL)
#' default(NULL, "my default")
#' default("a string", "my default")
#' @eval standalone_indiedown_export()
default <- function(x, default = "") {
  ans <- if (is.null(x)) default else x
  force(ans)
}

# nocov end

# Snapshots of rendered PDF documents ------------------------------------------

# `expect_pdf_snapshot(name, rmd, ..., tolerance, dpi, system_fonts, fonts)`
# renders an R Markdown document to PDF,
# rasterizes each page to PNG with poppler via the pdftools package,
# and compares each page with its snapshot
# using `testthat::expect_snapshot_file()`.
# Use it in the tests of a template package
# to catch unintended changes to the rendered pages,
# such as fonts, margins, title pages, or the placement of floats.
#
# `skip_if_no_pdf_snapshot()` skips the current test
# where PDF snapshots cannot be taken:
# on CRAN, on systems other than Linux,
# and without rmarkdown, pdftools, callr, showtext, sysfonts, pandoc, or LaTeX.
# `expect_pdf_snapshot()` calls it before rendering.
#
# Arguments:
# * `name`: Prefix of the snapshot file names, unique within a test file.
# * `rmd`: The lines of the R Markdown document, a character vector.
#   It is rendered in a temporary directory,
#   in a new environment whose parent is the global environment.
# * `...`: These dots are for future extensions and must be empty.
# * `tolerance`: The share of pixels, between 0 and 1,
#   that may differ between a page and its snapshot.
#   The default, 0, requires the PNG files to be byte-identical.
#   A positive value needs the png package.
# * `dpi`: Resolution of the rasterized pages, in dots per inch.
# * `system_fonts`: If `FALSE`, the default,
#   fontconfig sees only the fonts in `fonts`, or the fallback,
#   and so does the choice of the main font, see `resolve_fonts()`.
#   If `TRUE`, they see the fonts installed on the system.
# * `fonts`: Directory with the fonts that the template bundles.
#   The default, `NULL`, uses `inst/indiedown/fonts` of the template package.
#
# `expect_pdf_snapshot()` returns `NULL`, invisibly.
# `skip_if_no_pdf_snapshot()` returns `TRUE`, invisibly, if it does not skip.
#
# ## Snapshot files
#
# For `name = "report"`, the snapshot directory of the test file holds
# `report-page-01.png`, `report-page-02.png`, and so on, one for each page,
# and `report-environment.txt`, a record of the toolchain.
# The record lists the versions of the operating system, R, pandoc, LaTeX,
# poppler, fontconfig, FreeType, and the R packages involved,
# the font that fontconfig offers for Helvetica,
# and a hash of each font file that the template bundles,
# or of the fallback fonts.
# The record never fails a test:
# it is written when the snapshot is created and kept as is afterwards.
# To refresh the snapshots and the record,
# delete the snapshot files of `name` and run the tests again.
#
# If the document has more or fewer pages than there are page snapshots,
# the test fails, and only the pages that have a snapshot are compared.
# The page snapshots are looked up in the snapshot directory of the test file
# that testthat uses while it runs the tests,
# and an error is thrown if that directory cannot be determined.
# To accept a new page count, delete the snapshot files of `name`.
#
# Pixel-exact comparisons are only stable on a fixed toolchain,
# so `skip_if_no_pdf_snapshot()` skips on systems other than Linux.
# A positive `tolerance` accepts small differences.
#
# testthat deletes the snapshot files that a complete test run does not use.
# When it skips or when rendering fails,
# `expect_pdf_snapshot()` declares the existing snapshot files of `name`
# with `testthat::announce_snapshot_file()`,
# so that a test run on a system without LaTeX keeps them.
#
# ## Fonts
#
# R's `grDevices::pdf()` device, the default device of the knitr chunks,
# does not embed the fonts of a plot, it refers to a standard font by name.
# poppler substitutes the font that fontconfig offers for that name,
# so the rasterized plot text would depend on the fonts of the system.
# `expect_pdf_snapshot()` therefore sets the chunk option `fig.showtext = TRUE`
# while it renders the document, and only then,
# so that the showtext package draws the text of plots as outlines.
# It registers the font files that the template bundles in `fonts`
# with `sysfonts::font_add()` as the font family `""`,
# the family that base graphics and ggplot2 use by default,
# for example with `base_family = ""`.
# The font files are matched to the regular, bold, italic,
# and bold italic face by the words `bold`, `italic`, and `oblique`
# in their names.
# Plot text that names another family, such as `sans`,
# is drawn with the default font of the sysfonts package.
# The registration lasts for the R session, it is not undone.
# The template itself sets no graphics device and no plot font:
# the fonts of plots in regular documents are up to their authors.
#
# The text of the document is set by LaTeX,
# which finds the main font through fontconfig.
# Unless `system_fonts = TRUE`,
# `expect_pdf_snapshot()` lets fontconfig see
# only the fonts that the template bundles in `fonts`
# while the document is rendered and rasterized,
# so that a font installed on the system does not replace the bundled one.
# If the template bundles no fonts,
# Latin Modern Sans from the LaTeX installation is the fixed fallback.
# The pages are rasterized in a separate R process,
# because fontconfig reads its configuration only once per process.
# The choice of the main font also searches the font folders
# and uses systemfonts, which do not see this configuration,
# so `expect_pdf_snapshot()` sets the option `<package>.system_fonts = FALSE`,
# which turns them off,
# and unsets the options `<package>.font_path` and `<package>.mainfont`.
#
# ## Example
#
# In `tests/testthat/test-visual.R` of a template package called mydown:
#
#   test_that("the report looks right", {
#     expect_pdf_snapshot(
#       "report",
#       c(
#         "---",
#         "title: Report",
#         "date: January 1, 2026",
#         "output: mydown::mydown",
#         "---",
#         "",
#         "Some text."
#       )
#     )
#   })
expect_pdf_snapshot <- function(
  name,
  rmd,
  ...,
  tolerance = 0,
  dpi = 100,
  system_fonts = FALSE,
  fonts = NULL
) {
  rlang::check_dots_empty()
  check_pdf_snapshot_args(name, rmd, tolerance, dpi, system_fonts, fonts)

  # Unless the snapshots are taken, declare the existing ones,
  # so that a complete test run does not delete them as unused.
  taken <- FALSE
  withr::defer(if (!taken) announce_pdf_snapshot(name))

  skip_if_no_pdf_snapshot()
  if (tolerance > 0) {
    rlang::check_installed("png", "to compare PDF snapshots with a tolerance.")
  }

  dir <- withr::local_tempdir()
  if (is.null(fonts)) {
    fonts <- indiedown_path("fonts")
  }
  if (!system_fonts) {
    fonts <- visible_fonts(fonts, dir)
    withr::local_envvar(FONTCONFIG_FILE = write_fonts_conf(fonts, dir))
    withr::local_options(rlang::set_names(
      list(FALSE, NULL, NULL),
      indiedown_option_name(c("system_fonts", "font_path", "mainfont"))
    ))
  }

  input <- file.path(dir, paste0(name, ".Rmd"))
  writeLines(rmd, input)
  local_showtext(fonts)
  pdf <- rmarkdown::render(
    input,
    output_dir = dir,
    quiet = TRUE,
    envir = new.env(parent = globalenv())
  )

  pages <- rasterize_pdf(pdf, name, dpi)
  record <- paste0(name, "-environment.txt")
  writeLines(
    pdf_snapshot_environment(pdf, fonts, system_fonts),
    file.path(dir, record)
  )

  # A change of the page count fails, see "Snapshot files" above
  snaps <- pdf_snapshot_pages(name)
  same_count <- length(snaps) %in% c(0, length(pages))

  # Injecting the file name gives a readable label in failure messages
  compare <- compare_png(tolerance)
  for (page in pages[same_count | pages %in% snaps]) {
    rlang::inject(testthat::expect_snapshot_file(
      file.path(dir, !!page),
      compare = compare
    ))
  }
  rlang::inject(testthat::expect_snapshot_file(
    file.path(dir, !!record),
    compare = compare_true
  ))

  if (!same_count) {
    testthat::fail(sprintf(
      paste(
        "The page count of `%s` changed: %d rendered, %d in the snapshot.",
        "To accept the change, delete the snapshot files of `%s`",
        "and run the tests again."
      ),
      name,
      length(pages),
      length(snaps),
      name
    ))
  }

  # After a failure, the existing snapshot files are kept
  taken <- same_count
  invisible()
}

skip_if_no_pdf_snapshot <- function() {
  testthat::skip_on_cran()
  if (!is_linux()) {
    testthat::skip("PDF snapshots are pixel-exact on Linux only")
  }
  testthat::skip_if_not_installed("rmarkdown")
  testthat::skip_if_not_installed("pdftools")
  testthat::skip_if_not_installed("callr")
  testthat::skip_if_not_installed("showtext")
  testthat::skip_if_not_installed("sysfonts")
  testthat::skip_if_not(
    rmarkdown::pandoc_available(),
    "pandoc is not available"
  )
  testthat::skip_if_not(has_latex(), "LaTeX is not available")
  invisible(TRUE)
}

check_pdf_snapshot_args <- function(
  name,
  rmd,
  tolerance,
  dpi,
  system_fonts,
  fonts,
  call = rlang::caller_env()
) {
  if (!rlang::is_string(name) || !nzchar(name)) {
    rlang::abort("`name` must be a non-empty string.", call = call)
  }
  if (!is.character(rmd)) {
    rlang::abort("`rmd` must be a character vector.", call = call)
  }
  if (!is_number(tolerance) || tolerance < 0 || tolerance > 1) {
    rlang::abort("`tolerance` must be a number between 0 and 1.", call = call)
  }
  if (!is_number(dpi) || dpi <= 0) {
    rlang::abort("`dpi` must be a positive number.", call = call)
  }
  if (!rlang::is_bool(system_fonts)) {
    rlang::abort("`system_fonts` must be `TRUE` or `FALSE`.", call = call)
  }
  if (!is.null(fonts) && !(rlang::is_string(fonts) && dir.exists(fonts))) {
    rlang::abort(
      "`fonts` must be the path to a directory or `NULL`.",
      call = call
    )
  }
}

is_number <- function(x) {
  is.numeric(x) && length(x) == 1 && !is.na(x)
}

is_linux <- function() {
  identical(tolower(Sys.info()[["sysname"]]), "linux")
}

has_latex <- function() {
  (rlang::is_installed("tinytex") && tinytex::is_tinytex()) ||
    any(nzchar(Sys.which(c("pdflatex", "xelatex", "lualatex"))))
}

# Draws the text of plots with showtext, see "Fonts" above:
# registers the font files in `fonts` as the default font family,
# and sets the chunk option `fig.showtext` until the calling function ends.
# The option is a default of knitr's chunk options, a chunk can override it.
local_showtext <- function(fonts, .local_envir = parent.frame()) {
  files <- plot_font_files(fonts)
  if (!is.null(files)) {
    sysfonts::font_add(
      "",
      files$regular,
      files$bold,
      files$italic,
      files$bolditalic
    )
  }
  options <- knitr::opts_chunk$get()
  withr::defer(knitr::opts_chunk$restore(options), envir = .local_envir)
  knitr::opts_chunk$set(fig.showtext = TRUE)
  invisible()
}

# The paths of the font files of the four faces in a directory,
# or `NULL` if it has no font files.
# A missing face is `NULL`, which sysfonts replaces by the regular face.
plot_font_files <- function(dir) {
  files <- font_files(dir)
  if (length(files) == 0) {
    return(NULL)
  }
  names <- tolower(files)
  bold <- grepl("bold", names)
  italic <- grepl("italic|oblique", names)
  face <- function(is_face, default = NULL) {
    if (any(is_face)) file.path(dir, files[is_face][[1]]) else default
  }
  regular <- face(!bold & !italic, file.path(dir, files[[1]]))
  list(
    regular = regular,
    bold = face(bold & !italic),
    italic = face(italic & !bold),
    bolditalic = face(bold & italic)
  )
}

# The file names of the page snapshots of `name`
# in the snapshot directory of the current test file,
# or `NULL` outside of a test run.
# testthat exports no function for that directory:
# it is read from testthat's internal snapshot reporter,
# and an error says so if that is not possible,
# rather than silently skipping the check of the page count.
pdf_snapshot_pages <- function(name) {
  if (!testthat::is_testing()) {
    return(NULL)
  }
  snapshotter <- getOption("testthat.snapshotter")
  if (
    !rlang::is_string(snapshotter$snap_dir) ||
      !rlang::is_string(snapshotter$file)
  ) {
    rlang::abort(c(
      "Can't find the snapshot directory of the current test file.",
      i = paste(
        "The page count of a PDF snapshot is checked",
        "with internals of testthat, which may have changed."
      )
    ))
  }
  files <- dir(file.path(snapshotter$snap_dir, snapshotter$file))
  prefix <- paste0(name, "-")
  rest <- substring(files, nchar(prefix) + 1)
  files[startsWith(files, prefix) & grepl("^page-[0-9]+[.]png$", rest)]
}

announce_pdf_snapshot <- function(name) {
  if (!testthat::is_testing()) {
    return(invisible())
  }
  files <- unique(basename(list.files(
    testthat::test_path("_snaps"),
    recursive = TRUE
  )))
  prefix <- paste0(name, "-")
  rest <- substring(files, nchar(prefix) + 1)
  ours <- startsWith(files, prefix) &
    grepl("^(page-[0-9]+[.]png|environment[.]txt)$", rest)
  for (file in files[ours]) {
    testthat::announce_snapshot_file(file)
  }
  invisible()
}

font_files <- function(dir) {
  if (is.null(dir) || !dir.exists(dir)) {
    return(character())
  }
  files <- list.files(
    dir,
    pattern = "[.](otf|ttf|ttc|pfa|pfb)$",
    ignore.case = TRUE,
    recursive = TRUE
  )
  sort(files, method = "radix")
}

# The fallback is only added if the template bundles no fonts:
# next to the bundled fonts, fontconfig would offer it for some styles
# and mix two families in one plot.
visible_fonts <- function(fonts, dir) {
  if (length(font_files(fonts)) > 0) {
    return(fonts)
  }

  files <- paste0(
    "lmsans10-",
    c("regular", "bold", "oblique", "boldoblique"),
    ".otf"
  )
  paths <- run_command("kpsewhich", files)
  if (length(paths) != length(files)) {
    rlang::abort(c(
      "Can't find the fallback font Latin Modern Sans with `kpsewhich`.",
      i = paste(
        "Bundle fonts with the template in `inst/indiedown/fonts`,",
        "or set `system_fonts = TRUE`."
      )
    ))
  }

  fallback <- file.path(dir, "fonts-fallback")
  dir.create(fallback)
  file.copy(paths, fallback)
  fallback
}

write_fonts_conf <- function(fonts, dir) {
  conf <- file.path(dir, "fonts.conf")
  writeLines(
    c(
      "<?xml version=\"1.0\"?>",
      "<!DOCTYPE fontconfig SYSTEM \"fonts.dtd\">",
      "<fontconfig>",
      paste0("  <dir>", xml_escape(fonts), "</dir>"),
      paste0(
        "  <cachedir>",
        xml_escape(file.path(dir, "fontconfig-cache")),
        "</cachedir>"
      ),
      "</fontconfig>"
    ),
    conf
  )
  conf
}

xml_escape <- function(x) {
  x <- gsub("&", "&amp;", x, fixed = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  gsub(">", "&gt;", x, fixed = TRUE)
}

# Returns the file names of the pages, in the directory of `pdf`.
rasterize_pdf <- function(pdf, name, dpi) {
  # `filenames` is a format for sprintf(): page number and file extension
  prefix <- gsub("%", "%%", file.path(dirname(pdf), name), fixed = TRUE)
  pages <- callr::r(
    convert_pdf,
    args = list(pdf, paste0(prefix, "-page-%02d.%s"), dpi)
  )
  basename(pages)
}

# This function runs in a separate R process.
# Its environment is the global environment there,
# so it can only use other packages.
convert_pdf <- function(pdf, filenames, dpi) {
  pdftools::pdf_convert(
    pdf,
    format = "png",
    filenames = filenames,
    dpi = dpi,
    verbose = FALSE
  )
}

compare_png <- function(tolerance) {
  force(tolerance)
  function(old, new) {
    if (testthat::compare_file_binary(old, new)) {
      return(TRUE)
    }
    if (tolerance == 0) {
      return(FALSE)
    }
    old <- png::readPNG(old)
    new <- png::readPNG(new)
    if (!identical(dim(old), dim(new))) {
      return(FALSE)
    }
    differs <- old != new
    if (length(dim(differs)) == 3) {
      differs <- rowSums(differs, dims = 2) > 0
    }
    mean(differs) <= tolerance
  }
}

# The environment record is never compared
compare_true <- function(old, new) {
  TRUE
}

pdf_snapshot_environment <- function(pdf, fonts = NULL, system_fonts = FALSE) {
  info <- Sys.info()
  pandoc <- if (rmarkdown::pandoc_available()) {
    as.character(rmarkdown::pandoc_version())
  } else {
    NA_character_
  }
  packages <- c(
    "pdftools",
    "rmarkdown",
    "knitr",
    "tinytex",
    "showtext",
    "sysfonts"
  )
  files <- font_files(fonts)

  c(
    "# Toolchain used to generate the visual snapshots in this directory.",
    "# Pixel-exact comparisons are only stable on this toolchain; refreshed",
    "# only when the snapshots themselves are regenerated.",
    paste0("os: ", info[["sysname"]], " ", info[["release"]]),
    paste0("r: ", getRversion()),
    paste0("pandoc: ", pandoc),
    paste0("latex: ", latex_version(pdf)),
    paste0("poppler: ", pdftools::poppler_config()$version),
    paste0("fontconfig: ", fontconfig_version()),
    paste0("freetype: ", loaded_library("libfreetype")),
    paste0(packages, ": ", vapply(packages, package_version_or_na, "")),
    paste0("system fonts: ", if (system_fonts) "visible" else "hidden"),
    paste0("fc-match Helvetica: ", run_command("fc-match", "Helvetica")[1]),
    if (length(files) > 0) {
      paste0("font: ", files, " ", rlang::hash_file(file.path(fonts, files)))
    }
  )
}

pdf_producer <- function(pdf) {
  producer <- pdftools::pdf_info(pdf)$keys$Producer
  if (is.null(producer)) NA_character_ else producer
}

# The engine is inferred from the PDF producer that it writes
latex_engine <- function(producer) {
  if (is.na(producer)) {
    return(NULL)
  }
  if (grepl("xdvipdfmx", producer, ignore.case = TRUE)) {
    "xelatex"
  } else if (grepl("LuaTeX|LuaHBTeX", producer, ignore.case = TRUE)) {
    "lualatex"
  } else if (grepl("pdfTeX", producer, ignore.case = TRUE)) {
    "pdflatex"
  }
}

latex_version <- function(pdf) {
  producer <- pdf_producer(pdf)
  engine <- latex_engine(producer)
  if (is.null(engine)) {
    return(paste0("unknown, PDF producer: ", producer))
  }
  run_command(engine, "--version", stderr = TRUE)[1]
}

fontconfig_version <- function() {
  version <- run_command("fc-match", "--version", stderr = TRUE)[1]
  version <- sub("^fontconfig version ", "", version)
  paste0(version, " (", loaded_library("libfontconfig"), ")")
}

# The file name of a shared library loaded into this R process,
# with the full version number of the library
loaded_library <- function(lib, maps_file = "/proc/self/maps") {
  maps <- tryCatch(suppressWarnings(readLines(maps_file)), error = function(e) {
    character()
  })
  paths <- grep(paste0("/", lib, "[.]so"), maps, value = TRUE)
  if (length(paths) == 0) {
    return(NA_character_)
  }
  basename(sub("^.* ", "", paths[[1]]))
}

package_version_or_na <- function(package) {
  if (rlang::is_installed(package)) {
    as.character(utils::packageVersion(package))
  } else {
    NA_character_
  }
}

# The lines of the output of a command, or NA if it fails
run_command <- function(command, args, stderr = FALSE) {
  if (!nzchar(Sys.which(command))) {
    return(NA_character_)
  }
  out <- tryCatch(
    suppressWarnings(system2(command, args, stdout = TRUE, stderr = stderr)),
    error = function(e) NA_character_
  )
  if (length(out) == 0 || !is.null(attr(out, "status"))) {
    return(NA_character_)
  }
  out
}
